def average(marks):
    if len(marks) == 0:
        return 0
    return round(sum(marks) / len(marks), 1)

def group_counts(weights, width):
    d = {}
    for w in weights:
        k = int(w // width) * width
        d[k] = d.get(k, 0) + 1
    return dict(sorted(d.items()))

